CREATE OR REPLACE FUNCTION public.roomly_save_room(org uuid, room uuid, room_name text, room_location text, room_capacity integer, room_description text, room_equipment text[], active boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.roomly_admin(org) THEN RAISE EXCEPTION 'Wymagane uprawnienia administratora.'; END IF; IF room IS NULL OR room='00000000-0000-0000-0000-000000000000'::uuid THEN INSERT INTO public.rooms(organization_id,name,location,capacity,description,equipment,is_active) VALUES(org,trim(room_name),room_location,room_capacity,room_description,room_equipment,active) RETURNING id INTO result; ELSE UPDATE public.rooms SET name=trim(room_name),location=room_location,capacity=room_capacity,description=room_description,equipment=room_equipment,is_active=active WHERE id=room AND organization_id=org RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Sala nie należy do tej organizacji.'; END IF; END IF; INSERT INTO public.audit_events(organization_id,user_id,action,object_id) VALUES(org,auth.uid(),'room_saved',result); RETURN result; END $$;
CREATE FUNCTION public.roomly_account_cleanup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.user_roles WHERE user_id=OLD.id; DELETE FROM public.memberships WHERE user_id=OLD.id; RETURN OLD; END $$;
CREATE TRIGGER roomly_account_cleanup BEFORE DELETE ON auth.users FOR EACH ROW EXECUTE FUNCTION public.roomly_account_cleanup();
REVOKE ALL ON FUNCTION public.roomly_account_cleanup(), public.roomly_profile_signup() FROM PUBLIC, anon, authenticated;